(() => {
  const D=window.MORCHID_DATA;
  const app=document.getElementById('app');
  const STORAGE='morchid-progress-v2';
  const state={
    theme:localStorage.getItem('morchid-theme')||'light',
    focus:false,
    qcmIndex:0,
    qcmAnswers:{},
    qcmFilters:{domain:'all',difficulty:'all',status:'all',query:''},
    situationIndex:0,
    situationAnswers:{},
    flashIndex:0,
    flashFlipped:false,
    flashRatings:{},
    exam:null,
    readSchemes:[],
    readTerms:[],
    jury:[],
    activities:[],
    studyDays:[]
  };
  try{
    const saved=JSON.parse(localStorage.getItem(STORAGE)||'{}');
    Object.assign(state,saved);
    state.qcmAnswers=saved.qcmAnswers||{}; state.qcmFilters=saved.qcmFilters||state.qcmFilters;
    state.situationAnswers=saved.situationAnswers||{}; state.flashRatings=saved.flashRatings||{};
    state.readSchemes=saved.readSchemes||[]; state.readTerms=saved.readTerms||[]; state.jury=saved.jury||[];
    state.activities=saved.activities||[]; state.studyDays=saved.studyDays||[];
  }catch(e){}
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify({...state,focus:false}))}catch(e){}};
  const dayKey=()=>new Date().toISOString().slice(0,10);
  const recordActivity=(label,detail='')=>{
    const now=new Date(); const day=dayKey();
    if(!state.studyDays.includes(day))state.studyDays=[...state.studyDays.slice(-29),day];
    state.activities=[{label,detail,time:now.toLocaleTimeString('ar-MA',{hour:'2-digit',minute:'2-digit'}),day},...state.activities.filter(x=>x.label!==label).slice(0,4)]; save();
  };
  const percent=(a,b)=>b?Math.round(a/b*100):0;
  const domainName=id=>D.domainNames[id]||id;
  const route=()=>{if(location.hash)return location.hash.slice(1)||'home';const p=location.pathname.replace(/^\/+|\/+$/g,'');return p||'home'};
  const navKey=h=>h.startsWith('s-')?'schemes':h.startsWith('t-')?'glossary':h.startsWith('p-')?'plans':({schemes:'qcm',glossary:'flashcards',plans:'flashcards',practice:'qcm',quiz:'qcm',oral:'situations',jury:'progress',settings:'progress'}[h]||h);
  const toast=msg=>{const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),2400)};
  const pageHead=(eyebrow,title,sub='',action='')=>`<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
  const backHead=(title,sub='')=>`<div class="detail-head"><a class="back-link" href="#home">‹ الرئيسية</a><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`;
  const tri=labels=>`<svg viewBox="0 0 360 250" role="img" aria-label="مثلث بيداغوجي"><path d="M180 30L315 210H45Z" fill="none" stroke="#f5f1e7" stroke-width="2"/><g fill="#0f4c4a" stroke-width="3"><rect x="132" y="12" width="96" height="38" rx="11" stroke="#efd37c"/><rect x="260" y="191" width="96" height="38" rx="11" stroke="#f29cae"/><rect x="4" y="191" width="96" height="38" rx="11" stroke="#8dc7d7"/></g><g text-anchor="middle" fill="#f5f1e7" font-family="IBM Plex Sans Arabic"><text x="180" y="38" fill="#efd37c" font-size="17">${esc(labels[0])}</text><text x="308" y="217" fill="#f29cae" font-size="17">${esc(labels[1])}</text><text x="52" y="217" fill="#8dc7d7" font-size="17">${esc(labels[2])}</text><text x="252" y="118" font-size="15">التعليم</text><text x="108" y="118" font-size="15">التعلم</text><text x="180" y="213" font-size="15">التكوين</text></g></svg>`;
  const qcmStatus=q=>{const a=state.qcmAnswers[q.id];return a===undefined?'unanswered':a===q.answer?'correct':'wrong'};
  const qcmPool=()=>D.qcm.filter(q=>{
    const f=state.qcmFilters; const matchDomain=f.domain==='all'||q.domain===f.domain; const matchLevel=f.difficulty==='all'||q.difficulty===f.difficulty; const matchStatus=f.status==='all'||qcmStatus(q)===f.status; const text=`${q.question} ${q.concept} ${domainName(q.domain)}`.toLowerCase(); const matchQuery=!f.query||text.includes(f.query.toLowerCase()); return matchDomain&&matchLevel&&matchStatus&&matchQuery;
  });
  const qcmStats=()=>{const answered=Object.values(state.qcmAnswers);const correct=answered.filter((a,i)=>{const q=D.qcm.find(x=>x.id===Object.keys(state.qcmAnswers)[i]);return q&&a===q.answer}).length;return {answered:answered.length,correct,accuracy:percent(correct,answered.length),mastery:percent(correct,D.qcm.length)}};
  const recommendation=()=>{const stats=qcmStats(); if(!stats.answered)return {title:'ابدأ بسؤال واحد',text:'جلسة قصيرة الآن ستعطيك أول مؤشر على المجالات التي تحتاج تركيزًا.',href:'#qcm'}; const domains=Object.keys(D.domainNames).map(id=>{const qs=D.qcm.filter(q=>q.domain===id);const ans=qs.filter(q=>state.qcmAnswers[q.id]!==undefined);const ok=ans.filter(q=>state.qcmAnswers[q.id]===q.answer).length;return {id,total:qs.length,score:percent(ok,ans.length),answered:ans.length}}).filter(x=>x.answered).sort((a,b)=>a.score-b.score);const weak=domains[0];return weak?{title:`ركز على ${domainName(weak.id)}`,text:`دقتك الحالية في هذا المجال ${weak.score}%. أجب عن ثلاث بطاقات ثم راجع التفسير.`,href:'#qcm'}:{title:'حافظ على الإيقاع',text:'أكملت بداية جيدة. جرّب محاكاة قصيرة لتثبيت الاستدعاء تحت الضغط.',href:'#exam'}};
  const streak=()=>{let n=0;let d=new Date();while(state.studyDays.includes(d.toISOString().slice(0,10))){n++;d.setDate(d.getDate()-1)}return n};
  function home(){const stats=qcmStats();const rec=recommendation();return `<div class="page"><section class="hero"><div class="hero-inner"><p class="eyebrow" style="color:#f0c4a9">جلسة مراجعة هادئة</p><h1>افهم الفكرة، ثم حوّلها إلى جواب.</h1><p>بنك أسئلة، وضعيات من القسم، وبطاقات ذكية لمساعدتك على الاستعداد لمباراة التعليم بثقة.</p><div class="hero-actions"><a class="btn btn-primary" href="#qcm">ابدأ جلسة مراجعة <span>←</span></a><a class="btn btn-outline" href="#about">كيف يعمل المرشد؟</a></div></div></section><div class="quick-stats"><div class="stat-card"><strong>${stats.mastery}%</strong><span>إتقان الأسئلة</span></div><div class="stat-card"><strong>${stats.answered}</strong><span>سؤالًا تمت إجابته</span></div><div class="stat-card"><strong>${streak()}</strong><span>أيام متتالية</span></div><div class="stat-card"><strong>${D.flashcards.length}</strong><span>بطاقة مراجعة</span></div></div><div class="page-columns"><div><div class="section-title"><div><h2>أين تركز الآن؟</h2><p>توصية صغيرة مبنية على نشاطك المحلي</p></div></div><div class="panel recommendation"><div class="recommendation-icon">↗</div><div><h3>${rec.title}</h3><p>${rec.text}</p><a class="text-link" href="${rec.href}">ابدأ الآن ←</a></div></div><div class="section-title"><div><h2>مسارات المراجعة</h2><p>اختر طريقة تناسب وقتك اليوم</p></div></div><div class="action-grid"><a class="action-card" href="#qcm"><span class="action-icon">?</span><div><h3>أسئلة QCM</h3><p>اختبر فهمك مع تفسير فوري.</p></div></a><a class="action-card" href="#situations"><span class="action-icon">◈</span><div><h3>وضعيات مهنية</h3><p>فكر كمدرس داخل القسم.</p></div></a><a class="action-card" href="#flashcards"><span class="action-icon">▱</span><div><h3>بطاقات المفاهيم</h3><p>راجع بتكرار متباعد.</p></div></a><a class="action-card" href="#exam"><span class="action-icon">◷</span><div><h3>محاكاة الامتحان</h3><p>25 سؤالًا في 60 دقيقة.</p></div></a></div></div><aside><div class="section-title"><div><h2>تقدمك</h2><p>يتحفظ على هذا الهاتف فقط</p></div><a class="text-link" href="#progress">التفاصيل</a></div><div class="panel"><div class="panel-head"><div><h3>الإتقان العام</h3><p>${stats.correct} إجابة صحيحة من ${stats.answered}</p></div><strong style="color:var(--accent)">${stats.mastery}%</strong></div><div class="progress-line"><span style="width:${stats.mastery}%"></span></div><div class="progress-label"><span>واصل بخطوة واحدة اليوم</span><strong>${streak()?`اليوم ${streak()} من السلسلة`:'ابدأ سلسلتك'}</strong></div></div><div class="section-title"><div><h2>آخر نشاط</h2></div></div><div class="panel"><div class="activity-list">${state.activities.length?state.activities.slice(0,4).map(a=>`<div class="activity"><span class="activity-dot"></span><div><strong>${a.label}</strong><span>${a.detail||'جلسة مراجعة'} · ${a.time}</span></div></div>`).join(''):'<div class="empty">ستظهر هنا خطواتك الأولى. ابدأ بسؤال أو بطاقة.</div>'}</div></div></aside></div><p class="footer-note">المحتوى استرشادي للمراجعة. طابقه دائمًا مع الإطار المرجعي والتوجيهات الرسمية المعتمدة.</p></div>`}
  function qcm(){const pool=qcmPool();if(state.qcmIndex>=pool.length)state.qcmIndex=0;const q=pool[state.qcmIndex];return `<div class="page">${pageHead('بنك المراجعة','أسئلة QCM','أجب، اقرأ لماذا، ثم انتقل بخطوة واضحة.',`<button class="btn btn-outline focus-exit" id="exit-focus">الخروج من التركيز</button>`)}<div class="filters"><div class="search-box"><span>⌕</span><input id="qcm-search" type="search" value="${esc(state.qcmFilters.query)}" placeholder="ابحث في السؤال أو المفهوم" aria-label="البحث في الأسئلة"></div><div class="filter-row">${[['all','كل المجالات'],...Object.entries(D.domainNames)].map(([id,label])=>`<button class="chip ${state.qcmFilters.domain===id?'active':''}" data-filter="domain" data-value="${id}">${label}</button>`).join('')}</div><div class="filter-row"><button class="chip ${state.qcmFilters.difficulty==='all'?'active':''}" data-filter="difficulty" data-value="all">كل الصعوبات</button>${D.levelNames.map(x=>`<button class="chip ${state.qcmFilters.difficulty===x?'active':''}" data-filter="difficulty" data-value="${x}">${x}</button>`).join('')}<button class="chip ${state.qcmFilters.status==='wrong'?'active':''}" data-filter="status" data-value="wrong">أخطأت</button><button class="chip ${state.qcmFilters.status==='correct'?'active':''}" data-filter="status" data-value="correct">أجبت صحيحًا</button></div></div>${q?questionCard(q,pool):'<div class="empty">لا توجد أسئلة بهذا الاختيار. جرّب إزالة فلتر واحد.</div>'}</div>`}
  function questionCard(q,pool){const picked=state.qcmAnswers[q.id];const answered=picked!==undefined;return `<section class="question-card"><div class="session-top"><span class="question-domain">${domainName(q.domain)} · ${q.difficulty}</span><span class="session-count"><bdi dir="ltr"><strong>${state.qcmIndex+1}</strong> / ${pool.length}</bdi></span></div><div class="progress-line"><span style="width:${percent(state.qcmIndex+1,pool.length)}%"></span></div><h2>${q.question}</h2><div class="option-list">${q.options.map((o,i)=>`<button class="option ${answered&&i===q.answer?'correct':''} ${answered&&i===picked&&picked!==q.answer?'wrong':''}" data-qcm-option="${i}" ${answered?'disabled':''}>${o}</button>`).join('')}</div>${answered?`<div class="feedback"><strong>${picked===q.answer?'إجابة موفقة.':'راجع هذه الفكرة بهدوء.'}</strong><p>${q.explanation}</p><span class="concept-tag">المفتاح: ${q.concept}</span></div>`:''}<div class="session-actions">${answered?`<button class="btn btn-primary" id="next-qcm">${state.qcmIndex===pool.length-1?'ابدأ من جديد':'السؤال التالي'} ←</button>`:'<span class="muted small">اختر إجابة واحدة لترى التفسير.</span>'}<button class="btn btn-outline" id="start-focus">◌ تركيز</button></div><div class="question-grid">${pool.slice(0,Math.min(pool.length,20)).map((x,i)=>`<button class="question-dot ${i===state.qcmIndex?'current':''} ${qcmStatus(x)==='correct'?'correct':''} ${qcmStatus(x)==='wrong'?'wrong':''}" data-qcm-jump="${i}">${i+1}</button>`).join('')}</div></section>`}
  function situations(){const s=D.situations[state.situationIndex%D.situations.length];const picked=state.situationAnswers[s.id];return `<div class="page">${pageHead('مختبر القسم','وضعيات مهنية','اختر الإجراء الأنسب، ثم اقرأ التحليل كما لو كنت أمام اللجنة.')}<section class="situation-card"><div class="situation-meta"><span>${s.domain}</span><span>${state.situationIndex+1} / ${D.situations.length}</span></div><h2>${s.title}</h2><div class="scenario">${s.scenario}</div><div class="option-list">${s.options.map((o,i)=>`<button class="option ${picked!==undefined&&i===s.answer?'correct':''} ${picked!==undefined&&i===picked&&picked!==s.answer?'wrong':''}" data-sit-option="${i}" ${picked!==undefined?'disabled':''}>${o}</button>`).join('')}</div>${picked!==undefined?`<div class="analysis"><h3>التحليل التربوي</h3><p>${s.analysis}</p><p><strong>النظرية المرتبطة:</strong> ${s.theory}</p><p><strong>لماذا البدائل أقل مناسبة؟</strong> ${s.alternatives}</p><p><strong>تأمل المدرس:</strong> ${s.reflection}</p></div><button class="btn btn-primary" id="next-situation" style="margin-top:14px">وضعية تالية ←</button>`:'<p class="muted small" style="margin-top:13px">لا تبحث عن العبارة المثالية؛ ابحث عن القرار الذي يحمي التعلم ويستند إلى تشخيص.</p>'}</section><div class="section-title"><div><h2>خريطة الوضعيات</h2><p>اختر سيناريو آخر مباشرة</p></div></div><div class="question-grid">${D.situations.map((x,i)=>`<button class="question-dot ${i===state.situationIndex?'current':''} ${state.situationAnswers[x.id]!==undefined?'correct':''}" data-sit-jump="${i}">${i+1}</button>`).join('')}</div></div>`}
  function flashcards(){const card=D.flashcards[state.flashIndex%D.flashcards.length];const rating=state.flashRatings[card.id];const mastered=Object.values(state.flashRatings).filter(x=>x==='mastered').length;return `<div class="page"><div class="page-head"><div><p class="eyebrow">ذاكرة قصيرة، أثر طويل</p><h1>بطاقات المفاهيم</h1><p>اقلب البطاقة، استدع الفكرة، ثم أخبر المرشد بمستوى ثقتك.</p></div><span class="question-domain">${mastered} / ${D.flashcards.length} أتقنتها</span></div><div class="panel"><div class="deck-meter"><span>تقدم هذا deck</span><strong>${percent(mastered,D.flashcards.length)}%</strong></div><div class="progress-line" style="margin-top:8px"><span style="width:${percent(mastered,D.flashcards.length)}%"></span></div></div><div class="flash-layout" style="margin-top:13px"><div class="flashcard-scene"><div class="flashcard ${state.flashFlipped?'flipped':''}" data-flip><div class="flash-face"><span class="flash-label">المفهوم · اضغط للقلب</span><h2>${card.front}</h2><span class="muted small" style="margin-top:15px">فكّر في التعريف قبل أن تقلبها</span></div><div class="flash-face back"><span class="flash-label">التعريف والمثال</span><p>${card.back}</p><p style="margin-top:15px"><strong style="color:var(--accent)">مثال:</strong> ${card.example}</p><span class="muted small" style="margin-top:auto">اضغط للعودة إلى الوجه الأول</span></div></div></div>${state.flashFlipped?`<div class="rating-actions"><button class="btn btn-outline" data-rate="tomorrow">راجع غدًا</button><button class="btn btn-secondary" data-rate="today">راجع اليوم</button><button class="btn btn-primary" data-rate="mastered">أتقنتها</button></div>`:'<p class="muted small" style="text-align:center">القلب ليس اختبارًا؛ هو لحظة استدعاء نشط.</p>'}<div class="session-actions"><button class="btn btn-outline" id="prev-card">← السابقة</button><span class="muted small"><bdi dir="ltr">${state.flashIndex+1} / ${D.flashcards.length}</bdi>${rating?` · ${rating==='mastered'?'متقنة':'مجدولة'}`:''}</span><button class="btn btn-primary" id="next-card">التالية →</button></div></div></div>`}
  function startExam(){const shuffled=[...D.qcm].sort(()=>Math.random()-.5).slice(0,25);const now=Date.now();state.exam={questions:shuffled.map(q=>q.id),answers:{},flags:[],current:0,startedAt:now,endsAt:now+60*60*1000,finished:false};recordActivity('بدأت محاكاة الامتحان','25 سؤالًا · 60 دقيقة');render()}
  function exam(){if(!state.exam)return `<div class="page"><div class="panel exam-setup"><div class="exam-icon">◷</div><p class="eyebrow" style="justify-content:center">تدريب تحت الضغط</p><h2>محاكاة الامتحان</h2><p>25 سؤالًا من مجالات مختلفة، مع 60 دقيقة، شبكة تنقل، وتعليم للأسئلة التي تريد مراجعتها.</p><button class="btn btn-primary" id="start-exam">ابدأ المحاكاة</button></div><div class="section-title"><div><h2>قبل أن تبدأ</h2><p>جلسة واحدة بلا تشتيت</p></div></div><div class="panel"><ul class="bullet-list"><li>لا توجد إجابة صحيحة حتى تضغط على تسليم.</li><li>يمكنك تعليم أي سؤال والعودة إليه من الشبكة.</li><li>بعد النهاية سترى نقاط الضعف حسب المجال.</li></ul></div></div>`;if(state.exam.finished)return examResult();const left=Math.max(0,state.exam.endsAt-Date.now());const q=D.qcm.find(x=>x.id===state.exam.questions[state.exam.current]);const picked=state.exam.answers[q.id];return `<div class="page">${pageHead('محاكاة الامتحان','جلسة 60 دقيقة','أجب بهدوء. يمكنك التنقل وتعليم السؤال للمراجعة.') }<div class="exam-layout"><section class="question-card"><div class="exam-top"><span class="question-domain">${domainName(q.domain)} · ${q.difficulty}</span><span class="timer ${left<5*60*1000?'urgent':''}" id="exam-timer">${formatTime(left)}</span></div><h2>${q.question}</h2><div class="option-list">${q.options.map((o,i)=>`<button class="option ${picked!==undefined&&i===q.answer&&state.exam.finished?'correct':''} ${picked!==undefined&&i===picked&&!state.exam.finished?'selected':''}" data-exam-option="${i}">${o}</button>`).join('')}</div><div class="session-actions"><button class="flag-button ${state.exam.flags.includes(q.id)?'active':''}" id="flag-exam">${state.exam.flags.includes(q.id)?'★ معلّم للمراجعة':'☆ علّم للمراجعة'}</button><button class="btn btn-primary" id="next-exam">${state.exam.current===state.exam.questions.length-1?'مراجعة التسليم':'السؤال التالي'} ←</button></div></section><aside><div class="panel"><div class="panel-head"><div><h3>خريطة الأسئلة</h3><p>${Object.keys(state.exam.answers).length} تمت الإجابة</p></div></div><div class="question-grid">${state.exam.questions.map((id,i)=>`<button class="question-dot ${i===state.exam.current?'current':''} ${state.exam.answers[id]!==undefined?'correct':''} ${state.exam.flags.includes(id)?'wrong':''}" data-exam-jump="${i}">${i+1}</button>`).join('')}</div><button class="btn btn-primary" id="submit-exam" style="width:100%;margin-top:16px">تسليم الإجابات</button></div><div class="panel"><p class="muted small" style="margin:0">السؤال المعلّم ليس خاطئًا؛ هو فقط يحتاج عودة قبل التسليم.</p></div></aside></div></div>`}
  function formatTime(ms){const s=Math.max(0,Math.floor(ms/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
  function examResult(){const qs=state.exam.questions.map(id=>D.qcm.find(q=>q.id===id));const score=qs.filter(q=>state.exam.answers[q.id]===q.answer).length;const domains=[...new Set(qs.map(q=>q.domain))].map(id=>{const group=qs.filter(q=>q.domain===id);const ok=group.filter(q=>state.exam.answers[q.id]===q.answer).length;return {id,ok,total:group.length}});return `<div class="page">${pageHead('نتيجة المحاكاة','ماذا تعلمت من الجلسة؟','النتيجة ليست حكمًا؛ إنها خريطة للخطوة التالية.')}<div class="result-hero"><strong>${score} / ${qs.length}</strong><p>${score>=20?'أداء قوي جدًا. حافظ على تنويع المجالات.':score>=14?'بداية جيدة. راجع تفسير الأخطاء قبل جولة جديدة.':'استعمل النتيجة لتحديد مجال واحد تبدأ به اليوم.'}</p></div><div class="section-title"><div><h2>الأداء حسب المجال</h2><p>كل شريط يروي قصة صغيرة</p></div></div><div class="panel domain-bars">${domains.map(x=>`<div class="domain-row"><span>${domainName(x.id)}</span><div class="progress-line"><span style="width:${percent(x.ok,x.total)}%"></span></div><strong>${x.ok}/${x.total}</strong></div>`).join('')}</div><div class="panel" style="margin-top:12px"><div class="panel-head"><div><h3>نقاط الضعف</h3><p>أسئلة أخطأت فيها ويمكنك إعادة تعلمها</p></div></div><div class="list">${qs.filter(q=>state.exam.answers[q.id]!==q.answer).slice(0,5).map(q=>`<div class="activity"><span class="activity-dot"></span><div><strong>${q.concept}</strong><span>${domainName(q.domain)} · راجع التفسير في بنك الأسئلة.</span></div></div>`).join('')||'<div class="empty">لا توجد أخطاء في هذه الجولة. ممتاز.</div>'}</div></div><div class="session-actions"><button class="btn btn-primary" id="restart-exam">محاكاة جديدة</button><a class="btn btn-outline" href="#progress">لوحة التقدم</a></div></div>`}
  function progress(){const stats=qcmStats();const domainRows=Object.keys(D.domainNames).map(id=>{const qs=D.qcm.filter(q=>q.domain===id);const ans=qs.filter(q=>state.qcmAnswers[q.id]!==undefined);const ok=ans.filter(q=>state.qcmAnswers[q.id]===q.answer).length;return {id,total:qs.length,answered:ans.length,ok,score:percent(ok,ans.length)}});return `<div class="page">${pageHead('صورتك الكبيرة','لوحة التقدم','اعرف ما أتقنته وما يستحق جلسة قصيرة إضافية.')}<div class="metric-grid"><div class="metric"><strong>${stats.mastery}%</strong><span>إتقان عام</span></div><div class="metric"><strong>${stats.accuracy}%</strong><span>دقة الإجابات</span></div><div class="metric"><strong>${streak()}</strong><span>سلسلة أيام</span></div><div class="metric"><strong>${Object.keys(state.flashRatings).length}</strong><span>بطاقات لُوحظت</span></div></div><div class="section-title"><div><h2>التقدم حسب المجال</h2><p>المجال الفارغ يحتاج أول جلسة، لا حكمًا مسبقًا</p></div></div><div class="panel domain-bars">${domainRows.map(x=>`<div class="domain-row"><span>${domainName(x.id)}</span><div class="progress-line"><span style="width:${x.score}%"></span></div><strong>${x.answered?`${x.score}%`:'—'}</strong></div>`).join('')}</div><div class="page-columns"><div><div class="section-title"><div><h2>آخر نشاط</h2><p>أثر جلساتك القصيرة</p></div></div><div class="panel"><div class="activity-list">${state.activities.length?state.activities.map(a=>`<div class="activity"><span class="activity-dot"></span><div><strong>${a.label}</strong><span>${a.detail||''} · ${a.time}</span></div></div>`).join(''):'<div class="empty">لا نشاط بعد. ابدأ من بنك الأسئلة.</div>'}</div></div></div><div><div class="section-title"><div><h2>إشارة اليوم</h2></div></div><div class="panel recommendation"><div class="recommendation-icon">✓</div><div><h3>${recommendation().title}</h3><p>${recommendation().text}</p></div></div></div></div></div>`}
  function about(){return `<div class="page">${pageHead('عن المرشد','مراجعة تفهمك قبل أن تختبرك','مرشد التربية مساحة مراجعة استرشادية للمترشحين لمباراة التعليم في علوم التربية.')}<div class="panel"><h2 style="margin-top:0;font-size:18px">منهجية المرشد</h2><p class="muted" style="font-size:13px">نحن لا نضع التعريفات في عزلة؛ كل مفهوم يرتبط بسؤال أو مثال من القسم أو قرار تربوي. استخدم الجلسات القصيرة، اقرأ التفسير بعد كل إجابة، ثم تحدث بصوت عال كما لو كنت أمام اللجنة.</p><div class="action-grid" style="margin-top:15px"><div class="action-card"><span class="action-icon">01</span><div><h3>افهم</h3><p>مخطط أو بطاقة يحدد الفكرة.</p></div></div><div class="action-card"><span class="action-icon">02</span><div><h3>طبّق</h3><p>سؤال أو وضعية يختبر النقل.</p></div></div><div class="action-card"><span class="action-icon">03</span><div><h3>فسّر</h3><p>لماذا هذا القرار أنسب؟</p></div></div><div class="action-card"><span class="action-icon">04</span><div><h3>تتبّع</h3><p>تقدم محلي يساعدك على الاختيار.</p></div></div></div></div><div class="note" style="margin-top:14px"><strong>تنبيه:</strong> المحتوى استرشادي. راجع الإطار المرجعي والوثائق الرسمية الخاصة بدورتك، ولا تعتبر البطاقات بديلًا عن التكوين أو التوجيهات المعتمدة.</div></div>`}
  function schemes(){const query=state.qcmFilters.query;const shown=D.schemes.filter(x=>!query||`${x.title} ${x.subtitle} ${x.summary}`.includes(query));return `<div class="page">${pageHead('مكتبة الفهم','المخططات الجاهزة',`${D.schemes.length} خرائط لفهم علوم التربية والديداكتيك`)}<div class="search-box" style="margin-bottom:13px"><span>⌕</span><input id="scheme-search" type="search" value="${esc(query)}" placeholder="ابحث عن مثلث، تقويم، كفاية..." aria-label="البحث في المخططات"></div><div class="list">${shown.length?shown.map((x,i)=>`<a class="list-card" href="#s-${x.id}"><span class="card-number">${String(i+1).padStart(2,'0')}</span><div><h3>${x.title}${state.readSchemes.includes(x.id)?'<em class="tag">تمت</em>':''}</h3><p>${x.subtitle}</p></div><span class="arrow">‹</span></a>`).join(''):'<div class="empty">لم نعثر على مخطط بهذا البحث.</div>'}</div></div>`}
  function schemeDetail(x){if(!state.readSchemes.includes(x.id)){state.readSchemes.push(x.id);recordActivity('راجعت مخططًا',x.title)}return `<div class="page">${backHead(x.title,x.subtitle)}<div class="chalkboard">${x.id==='triangle'?tri(x.key):`<div class="flow">${x.flow.map((s,i)=>`<div class="flow-step"><strong>${i+1}. ${s[0]}</strong><span>${s[1]}</span></div>${i<x.flow.length-1?'<div class="flow-arrow">↓</div>':''}`).join('')}</div>`}</div><section class="info-block"><h2>الفكرة في سطرين</h2><p>${x.summary}</p><ul class="bullet-list">${x.bullets.map(b=>`<li>${b}</li>`).join('')}</ul></section><div class="note"><strong>مفتاح الحفظ:</strong> ${x.key.join(' · ')}</div><section class="info-block"><h2>معلومة توسّع فهمك</h2><ul class="bullet-list">${x.facts.map(f=>`<li>${f}</li>`).join('')}</ul></section><div class="session-actions"><a class="btn btn-primary" href="#qcm">ثبّت الفكرة بسؤال</a><a class="btn btn-outline" href="#schemes">كل المخططات</a></div></div>`}
  function glossary(){const query=state.qcmFilters.query;const shown=D.terms.filter(t=>!query||`${t.title} ${t.definition} ${t.category}`.includes(query));return `<div class="page">${pageHead('مفاتيح الجواب','قاموس المفاهيم','تعريف قصير، مصدر، ثم مثال يقرّب المفهوم من القسم.')}<div class="search-box" style="margin-bottom:13px"><span>⌕</span><input id="term-search" type="search" value="${esc(query)}" placeholder="ابحث عن مفهوم أو صاحب نظرية..." aria-label="البحث في المفاهيم"></div><div class="list">${shown.length?shown.map(t=>`<a class="definition-card" href="#t-${t.id}"><h3>${t.title}${state.readTerms.includes(t.id)?'<em class="tag">راجعت</em>':''}</h3><span class="source">${t.category} · ${t.source}</span><p>${t.definition}</p></a>`).join(''):'<div class="empty">لا توجد نتيجة بهذا البحث.</div>'}</div></div>`}
  function termDetail(t){if(!state.readTerms.includes(t.id)){state.readTerms.push(t.id);recordActivity('راجعت مفهومًا',t.title)}return `<div class="page">${backHead(t.title,`${t.category} · ${t.source}`)}<div class="definition-card"><h3>التعريف</h3><p>${t.definition}</p></div><section class="info-block"><h2>كيف تستعمله في جوابك؟</h2><p>ابدأ بتعريف المفهوم، ثم اربطه بوظيفة المدرس أو نشاط المتعلم، وأنهِ بمثال قصير من وضعية صفية. التعريف مفتاح، وليس بديلًا عن الفهم.</p></section><a class="btn btn-primary" href="#glossary">مفهوم آخر</a></div>`}
  function plans(){return `<div class="page">${pageHead('من الفكرة إلى الحصة','جذاذات نموذجية','نماذج استرشادية كيّفها مع السلك والمادة والكتاب المدرسي')}<div class="list">${D.plans.map(p=>`<a class="plan-card" href="#p-${p.id}"><h3>${p.title}</h3><p>${p.level}</p><div class="plan-meta"><span class="pill">${p.duration} دقيقة</span><span class="pill">${p.objective.length} أهداف</span></div></a>`).join('')}</div></div>`}
  function planDetail(p){return `<div class="page">${backHead(p.title,`${p.level} · مدة الحصة ${p.duration} دقيقة`)}<section class="info-block"><h2>الأهداف الإجرائية</h2><ul class="bullet-list">${p.objective.map(o=>`<li>${o}</li>`).join('')}</ul></section><div class="note"><strong>المكتسبات القبلية:</strong> ${p.prior}</div><section class="info-block"><h2>سير الحصة</h2><div class="panel">${p.steps.map(s=>`<div class="activity"><span class="activity-dot"></span><div><strong>${s[0]} · ${s[1]} د</strong><span>${s[2]}</span></div></div>`).join('')}</div></section><a class="btn btn-primary" href="#progress">قيّم جاهزيتك</a></div>`}
  function practice(){return `<div class="page">${pageHead('تدريب عملي','حوّل المعرفة إلى أداء','ثلاثة مسارات قصيرة تساعدك على التقدم دون تشتيت.')}<div class="action-grid"><a class="action-card" href="#qcm"><span class="action-icon">?</span><div><h3>اختبار المفاهيم</h3><p>${D.qcm.length} سؤالًا مع تفسير وتصفية.</p></div></a><a class="action-card" href="#situations"><span class="action-icon">◈</span><div><h3>وضعيات شفوية</h3><p>قرارات صفية وتحليل أمام اللجنة.</p></div></a><a class="action-card" href="#flashcards"><span class="action-icon">▱</span><div><h3>بطاقات الاستدعاء</h3><p>راجع ثم قيّم ثقتك.</p></div></a><a class="action-card" href="#exam"><span class="action-icon">◷</span><div><h3>محاكاة كاملة</h3><p>25 سؤالًا في 60 دقيقة.</p></div></a></div><div class="section-title"><div><h2>روتين 20 دقيقة</h2><p>جلسة صغيرة قابلة للتكرار</p></div></div><div class="panel"><div class="activity-list"><div class="activity"><span class="activity-dot"></span><div><strong>7 دقائق · افهم</strong><span>اقرأ مخططًا واكتب مفتاحه من الذاكرة.</span></div></div><div class="activity"><span class="activity-dot"></span><div><strong>7 دقائق · طبّق</strong><span>أجب عن سؤال أو حل وضعية قصيرة.</span></div></div><div class="activity"><span class="activity-dot"></span><div><strong>6 دقائق · تكلّم</strong><span>قدّم جوابك بصوت عال ثم سجل تعثرًا واحدًا.</span></div></div></div></div></div>`}
  function jury(){const score=state.jury.length*2;return `<div class="page">${pageHead('تأمل مهني','فحص الجذاذة','حدد المعايير التي تحققت بصدق لتحصل على نقطة أولية من 20.')}<div class="list">${D.jury.map((x,i)=>`<button class="list-card ${state.jury.includes(i)?'selected':''}" data-jury="${i}" style="text-align:right;color:var(--ink)"><span class="card-number">${state.jury.includes(i)?'✓':i+1}</span><span>${x}</span></button>`).join('')}</div><div class="result-hero" style="margin-top:14px"><strong>${score} / 20</strong><p>${score>=16?'جاهزة للعرض مع تحسينات طفيفة.':score>=12?'تحتاج إلى تحسينات قبل العرض.':'أعد بناء العناصر الأساسية ثم أعد الفحص.'}</p></div></div>`}
  function settings(){return `<div class="page">${pageHead('مساحتك','الإعدادات','تحكم في مظهر التطبيق وبيانات هذا الجهاز.')}<div class="panel"><h2 style="font-size:16px;margin-top:0">التقدم المحلي</h2><p class="muted small">يحفظ التطبيق نشاطك على هذا الهاتف فقط، ولا يرسل الإجابات إلى خادم.</p><button class="btn btn-outline" id="reset-progress">إعادة ضبط التقدم</button></div></div>`}
  let examTimer=null;
  function render(){if(examTimer){clearInterval(examTimer);examTimer=null}const h=route();let html='';if(h==='home')html=home();else if(h==='qcm')html=qcm();else if(h==='situations')html=situations();else if(h==='flashcards')html=flashcards();else if(h==='exam')html=exam();else if(h==='progress')html=progress();else if(h==='about')html=about();else if(h==='schemes')html=schemes();else if(h==='glossary')html=glossary();else if(h==='plans')html=plans();else if(h==='practice')html=practice();else if(h==='quiz')html=qcm();else if(h==='oral')html=situations();else if(h==='jury')html=jury();else if(h==='settings')html=settings();else if(h.startsWith('s-')){const x=D.schemes.find(x=>`s-${x.id}`===h);html=x?schemeDetail(x):schemes()}else if(h.startsWith('t-')){const x=D.terms.find(x=>`t-${x.id}`===h);html=x?termDetail(x):glossary()}else if(h.startsWith('p-')){const x=D.plans.find(x=>`p-${x.id}`===h);html=x?planDetail(x):plans()}else html=home();app.innerHTML=html;app.focus({preventScroll:true});document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===navKey(h)));bind();if(h==='exam'&&state.exam&&!state.exam.finished)startExamTimer();}
  function startExamTimer(){examTimer=setInterval(()=>{const el=document.getElementById('exam-timer');if(!state.exam||state.exam.finished)return;const left=Math.max(0,state.exam.endsAt-Date.now());if(el){el.textContent=formatTime(left);el.classList.toggle('urgent',left<5*60*1000)}if(left===0){state.exam.finished=true;recordActivity('انتهت محاكاة الامتحان','تم التسليم تلقائيًا');render()}},1000)}
  function bind(){document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.qcmFilters[b.dataset.filter]=b.dataset.value;state.qcmIndex=0;render()}));document.getElementById('qcm-search')?.addEventListener('input',e=>{state.qcmFilters.query=e.target.value.trim();state.qcmIndex=0;save();render()});document.getElementById('scheme-search')?.addEventListener('input',e=>{state.qcmFilters.query=e.target.value.trim();render()});document.getElementById('term-search')?.addEventListener('input',e=>{state.qcmFilters.query=e.target.value.trim();render()});document.querySelectorAll('[data-qcm-option]').forEach(b=>b.addEventListener('click',()=>{const pool=qcmPool();const q=pool[state.qcmIndex];state.qcmAnswers[q.id]=Number(b.dataset.qcmOption);recordActivity('أجبت عن سؤال',`${domainName(q.domain)} · ${qcmStatus(q)==='correct'?'صحيح':'يحتاج مراجعة'}`);render()}));document.getElementById('next-qcm')?.addEventListener('click',()=>{const pool=qcmPool();state.qcmIndex=state.qcmIndex<pool.length-1?state.qcmIndex+1:0;render()});document.querySelectorAll('[data-qcm-jump]').forEach(b=>b.addEventListener('click',()=>{state.qcmIndex=Number(b.dataset.qcmJump);render()}));document.getElementById('start-focus')?.addEventListener('click',()=>{state.focus=true;document.body.classList.add('focus-mode');render()});document.getElementById('exit-focus')?.addEventListener('click',()=>{state.focus=false;document.body.classList.remove('focus-mode');render()});document.querySelectorAll('[data-sit-option]').forEach(b=>b.addEventListener('click',()=>{const s=D.situations[state.situationIndex];state.situationAnswers[s.id]=Number(b.dataset.sitOption);recordActivity('حللت وضعية مهنية',s.domain);render()}));document.getElementById('next-situation')?.addEventListener('click',()=>{state.situationIndex=(state.situationIndex+1)%D.situations.length;render()});document.querySelectorAll('[data-sit-jump]').forEach(b=>b.addEventListener('click',()=>{state.situationIndex=Number(b.dataset.sitJump);render()}));document.querySelector('[data-flip]')?.addEventListener('click',()=>{state.flashFlipped=!state.flashFlipped;render()});document.querySelectorAll('[data-rate]').forEach(b=>b.addEventListener('click',()=>{const card=D.flashcards[state.flashIndex];state.flashRatings[card.id]=b.dataset.rate==='mastered'?'mastered':'scheduled';recordActivity('راجعت بطاقة',card.front);state.flashFlipped=false;state.flashIndex=(state.flashIndex+1)%D.flashcards.length;render()}));document.getElementById('next-card')?.addEventListener('click',()=>{state.flashIndex=(state.flashIndex+1)%D.flashcards.length;state.flashFlipped=false;render()});document.getElementById('prev-card')?.addEventListener('click',()=>{state.flashIndex=(state.flashIndex-1+D.flashcards.length)%D.flashcards.length;state.flashFlipped=false;render()});document.getElementById('start-exam')?.addEventListener('click',startExam);document.querySelectorAll('[data-exam-option]').forEach(b=>b.addEventListener('click',()=>{if(!state.exam||state.exam.finished)return;const q=D.qcm.find(x=>x.id===state.exam.questions[state.exam.current]);state.exam.answers[q.id]=Number(b.dataset.examOption);save();render()}));document.getElementById('next-exam')?.addEventListener('click',()=>{if(state.exam.current<state.exam.questions.length-1)state.exam.current++;else toast('راجع الشبكة ثم اضغط على تسليم الإجابات');save();render()});document.querySelectorAll('[data-exam-jump]').forEach(b=>b.addEventListener('click',()=>{state.exam.current=Number(b.dataset.examJump);save();render()}));document.getElementById('flag-exam')?.addEventListener('click',()=>{const id=state.exam.questions[state.exam.current];state.exam.flags=state.exam.flags.includes(id)?state.exam.flags.filter(x=>x!==id):[...state.exam.flags,id];save();render()});document.getElementById('submit-exam')?.addEventListener('click',()=>{state.exam.finished=true;recordActivity('سلّمت محاكاة الامتحان','راجع نقاط الضعف حسب المجال');render()});document.getElementById('restart-exam')?.addEventListener('click',()=>{state.exam=null;render()});document.querySelectorAll('[data-jury]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.jury);state.jury=state.jury.includes(i)?state.jury.filter(x=>x!==i):[...state.jury,i];save();render()}));document.getElementById('reset-progress')?.addEventListener('click',()=>{state.qcmAnswers={};state.situationAnswers={};state.flashRatings={};state.exam=null;state.readSchemes=[];state.readTerms=[];state.jury=[];state.activities=[];state.studyDays=[];save();toast('تمت إعادة ضبط التقدم');render()});}
  document.getElementById('theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;localStorage.setItem('morchid-theme',state.theme)});
  document.getElementById('focus-toggle').addEventListener('click',()=>{state.focus=!state.focus;document.body.classList.toggle('focus-mode',state.focus);toast(state.focus?'تم تفعيل وضع التركيز':'تم إيقاف وضع التركيز')});
  document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('focus-mode',state.focus);addEventListener('hashchange',()=>{state.qcmFilters.query='';render()});render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
